create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', phone text, avatar_path text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.user_roles (user_id uuid not null references public.profiles(id) on delete cascade, role text not null check (role in ('customer','merchant','rider','support','admin')), created_at timestamptz not null default now(), primary key (user_id, role));
create table if not exists public.service_areas (id uuid primary key default gen_random_uuid(), city text not null, state text not null default '', is_active boolean not null default false, created_at timestamptz not null default now(), unique(city, state));
create table if not exists public.delivery_zones (id uuid primary key default gen_random_uuid(), service_area_id uuid not null references public.service_areas(id) on delete cascade, name text not null, fee_kobo integer not null default 0 check (fee_kobo >= 0), min_order_kobo integer not null default 0 check (min_order_kobo >= 0), is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.customer_addresses (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.profiles(id) on delete cascade, label text not null, line1 text not null, area text not null, city text not null, instructions text, is_default boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.merchants (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, business_name text not null, approval_status text not null default 'pending' check (approval_status in ('pending','approved','rejected','suspended')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.stores (id uuid primary key default gen_random_uuid(), merchant_id uuid not null references public.merchants(id) on delete cascade, slug text unique not null, name text not null, category text not null, description text not null default '', is_open boolean not null default false, is_approved boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.riders (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, approval_status text not null default 'pending' check (approval_status in ('pending','approved','rejected','suspended')), is_online boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id));
create trigger set_updated before update on public.profiles for each row execute function public.set_updated_at();
create trigger set_updated before update on public.customer_addresses for each row execute function public.set_updated_at();
create trigger set_updated before update on public.merchants for each row execute function public.set_updated_at();
create trigger set_updated before update on public.stores for each row execute function public.set_updated_at();
create trigger set_updated before update on public.riders for each row execute function public.set_updated_at();
